127	    private static List<Integer> argTopK(double[] s, int k, int skipIdx) {
128	        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingDouble(a -> a[1]));
129	        for (int i = 0; i < s.length; i++) {
130	            if (i == skipIdx) continue;
131	            int scoreScaled = (int) TMath.round(s[i] * 1_000_000.0);
132	            if (pq.size() < k) {
133	                pq.offer(new int[]{i, scoreScaled});
134	            } else if (scoreScaled > pq.peek()[1]) {
135	                pq.poll();
136	                pq.offer(new int[]{i, scoreScaled});
137	            }
138	        }
139	        ArrayList<Integer> idxs = new ArrayList<>();
140	        while (!pq.isEmpty()) idxs.add(pq.poll()[0]);
141	        Collections.sort(idxs); // order not important
142	        return idxs;
143	    }
