237	    private static void addLatentMeasuredImpurities(Graph g, List<Node> latents, List<Node> measured,
238	                                                    int count, Random rng) {
239	        if (count <= 0 || latents.isEmpty() || measured.isEmpty()) return;
240	        int tries = 0, added = 0, maxTries = count * 20;
241	        while (added < count && tries++ < maxTries) {
242	            Node L = latents.get(rng.nextInt(latents.size()));
243	            Node X = measured.get(rng.nextInt(measured.size()));
244	            if (g.isParentOf(L, X)) continue;              // already a parent
245	            if (L == X) continue;
246	            if (g.isAdjacentTo(X, L)) continue;
247	            g.addDirectedEdge(L, X);
248	            added++;
249	        }
250	    }
