252	    private static void addMeasuredMeasuredParents(Graph g, List<Node> measured, int count, Random rng) {
253	        if (count <= 0 || measured.size() < 2) return;
254	        int tries = 0, added = 0, maxTries = count * 50;
255	        while (added < count && tries++ < maxTries) {
256	            int i = rng.nextInt(measured.size());
257	            int j = rng.nextInt(measured.size());
258	            if (i == j) continue;
259	
260	            Node A = measured.get(TMath.min(i, j)); // bias lower -> higher
261	            Node B = measured.get(TMath.max(i, j));
262	
263	            if (g.isAdjacentTo(A, B)) continue;           // any edge already between them? skip
264	            if (hasDirectedPath(g, B, A)) continue;       // adding A->B would create a cycle
265	            g.addDirectedEdge(A, B);
266	            added++;
267	        }
268	    }
