270	    // Simple DFS over directed edges only
271	    private static boolean hasDirectedPath(Graph g, Node from, Node to) {
272	        if (from == to) return true;
273	        Deque<Node> stack = new ArrayDeque<>();
274	        Set<Node> seen = new HashSet<>();
275	        stack.push(from);
276	        seen.add(from);
277	
278	        while (!stack.isEmpty()) {
279	            Node cur = stack.pop();
280	            if (cur == to) return true;
281	            for (Node child : g.getChildren(cur)) { // directed out-neighbors
282	                if (seen.add(child)) stack.push(child);
283	            }
284	        }
285	        return false;
286	    }
